eval("\nmodule.exports = {\n    en: {\n        OurCoreValues: {\n            title: `DO YOU QUALIFY FOR A COMPENSATION`,\n            _1: {\n                title: `High effectiveness`,\n                desc: `If your flight delayed for 3+ hours you are eligible for compensation.`\n            },\n            _2: {\n                title: `Accessibility`,\n                desc: `We offer you service in timely manner 7 days a week, 24 hours`\n            },\n            _3: {\n                title: `Reliable Partner`,\n                desc: `Our company is a trustworthy and trusted ally in every situation`\n            },\n            _4: {\n                title: `Professionalism`,\n                desc: `Our company is distinguished by qualified and professional lawyers with a high level of knowledge.`\n            },\n            _5: {\n                title: `No obligations`,\n                desc: `Our company works on a “no win, no fee” basis. So if we don’t win the case, we won’t charge you any fee for our services`\n            },\n            _6: {\n                title: `Simplicity`,\n                desc: `Getting compensation with us is very easy. You only need to fill the form and we handle all the other procedures.`\n            },\n            _7: {\n                title: `Partner companies`,\n                desc: `We cooperate with the world’s best law firms, this fact gives us the advantage over the airlines, which we use to get your compensation`\n            }\n        }\n    },\n    ka: {\n        OurCoreValues: {\n            title: `ჩვენი ძირითადი ფასეულობები`,\n            _1: {\n                title: `მაღალეფექტურობა`,\n                desc: `აღებული კეისების უმეტესობა წარმატებულია და სრულიად აკმაყოფილებს მომხმარებლის მოთხოვნებს.`\n            },\n            _2: {\n                title: `ხელმისაწვდომობა`,\n                desc: `ჩვენი კომპანია გთავაზობთ კონსულტაციას კვირაში 7 დღე, 24 სთ-ს განმავლობაში.`\n            },\n            _3: {\n                title: `საიმედო პარტნიორი`,\n                desc: `ჩვენი კომპანია მომხმარებლისთვის  საიმედო და ყველა სიტუაციაში დასაყრდენ ერთგულ მოკავშირეს წარმოადგენს.`\n            },\n            _4: {\n                title: `პროფესიონალიზმი`,\n                desc: `ჩვენი კომპანია გამოირჩევა პროფესიონალი, კვალიფიციური იურისტებით და საქმის მაღალ დონეზე ცოდნით.`\n            },\n            _5: {\n                title: `არანაირი ვალდებულება`,\n                desc: `ჩვენი მომსახურებით სარგებლობის შემთხვევაში არ გიწევთ არანაირი თანხის  გადახდა მის წარმატებით  დასრულებამდე.`\n            },\n            _6: {\n                title: `სიმარტივე`,\n                desc: `ჩვენთან კომპენსაციის მიღება ძალიან მარტივია. თქვენ ავსებთ აპლიკაციას, ყველა დანარჩენ პროცედურას ვაგვარებთ ჩვენ.`\n            },\n            _7: {\n                title: `პარტნიორი კომპანიები`,\n                desc: `ჩვენ ვთანამშრომლობთ მსოლფიოს საუკეთესო იურიდიულ კომპანიებთან, ეს გვანიჭებს უპირატესობას ავიაკომპანიებთან,  რასაც ვიყენებთ თქვენი კომპენსაციის მისაღებად`\n            }\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/views/About Us/Our core values/OurCoreValues.module.js\n");

