eval("\nmodule.exports = {\n    en: {\n        cancelledflights: {\n            header: `The most common reasons why the flights get cancelled`,\n            text: ` Summer, vacations, holidays, these are periods when most people plan their dream trips.\r\n         Everything is ready and only thing you have to do, is to go to the airport and get in \r\n         your plane.\r\n        What is the worst that may happen when you are going to start your trip? – Words on \r\n        the huge screen: …..flight cancelled!`,\n            read: `Read More`\n        }\n    },\n    ka: {\n        cancelledflights: {\n            header: `ფრენების გაუქმების ყველაზე გავრცელებული მიზეზები`,\n            text: ` ზაფხული, არდადეგები,  ეს ის პერიოდებია, როდესაც ადამიანების უმეტესობა გეგმავს საოცნებო მოგზაურობებს.\r\n             ყველაფერი მზად არის და ერთადერთი რაც უნდა გააკეთო არის აეროპორტში წასვლა და შესვლა\r\n            შენი თვითმფრინავი.\r\n            რა არის ყველაზე უარესი, რაც შეიძლება მოხდეს, როდესაც აპირებთ მოგზაურობის დაწყებას? - სიტყვები\r\n            უზარმაზარი ეკრანი: …..ფრენა გაუქმდა!`,\n            read: `ნახვა`\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/views/Blog page/CancelledFlights/cancelledflights.module.js\n");

